import { boolean, date, decimal, entity, int, many, one, role, text, uuid } from '@microsoft/rayfin-core';
import { Source } from '@microsoft/rayfin-connectors';
import type { AutoGenerated } from '@microsoft/rayfin-connectors';
import { Category } from './Category.js';
import { StockLevel } from './StockLevel.js';

@role('anonymous', ['read'], { exclude: ['ownerEmail'] })
@role('authenticated', ['read', 'create'])
@role('authenticated', ['update', 'delete'], {
  policy: (claims, item) => claims.email.eq(item.ownerEmail),
})
@entity()
export class Product extends Source({ schema: 'sales', table: 'products', primaryKey: ['productId'] }) {
  // DEFAULT newid(): server-generated.
  @uuid({ column: 'product_id' })
  productId!: AutoGenerated<string>;

  @int({ column: 'category_id' })
  categoryId!: number;

  @text({ max: 200 })
  name!: string;

  @decimal({ precision: 10, scale: 2 })
  price!: number;

  @boolean({ column: 'in_stock' })
  inStock!: boolean;

  // DEFAULT sysutcdatetime(): server-generated.
  @date({ column: 'created_at' })
  createdAt!: AutoGenerated<Date>;

  @text({ column: 'owner_email', max: 320 })
  ownerEmail!: string;

  @one(() => Category, { sourceFields: ['categoryId'], targetFields: ['categoryId'] })
  category!: Category;

  @many(() => StockLevel, { sourceFields: ['productId'], targetFields: ['productId'] })
  stockLevels!: StockLevel[];
}
